-- Mengembalikan 5 view apam ke definisi sebelum 21_employees_hr_view.sql (isi lama tertanam), lalu menghapus view employees_hr.
-- Jalankan:  mysql --comments -u <user> -p < 22_employees_hr_rollback.sql   (aman diulang). Deploy ulang kode lama SEBELUM atau bersamaan
-- bila kode baru (membaca employees_hr) sudah terpasang, karena employees_hr dihapus di akhir.


-- list_detail_pic_task
CREATE OR REPLACE ALGORITHM=UNDEFINED DEFINER=`ptpemaco`@`localhost` SQL SECURITY DEFINER VIEW `ptpemaco_apam`.`list_detail_pic_task` AS
select `c`.`first_name` AS `pic_task`,`ptpemaco_apam`.`a`.`task_id` AS `task_id`,`ptpemaco_apam`.`a`.`task_title` AS `task_title`,`ptpemaco_apam`.`a`.`project_id` AS `project_id`,`ptpemaco_apam`.`a`.`project_name` AS `project_name`,`ptpemaco_apam`.`a`.`divisi` AS `divisi`,`ptpemaco_apam`.`a`.`created_by` AS `created_by`,`ptpemaco_apam`.`a`.`progress` AS `progress`,`ptpemaco_apam`.`a`.`start_date` AS `start_date`,`ptpemaco_apam`.`a`.`end_date` AS `end_date` from ((`ptpemaco_apam`.`list_task_final` `a` join `ptpemaco_apam`.`project_task_pics` `b`) join `ptpemaco_apam`.`employees` `c`) where ((`b`.`task_id` = `ptpemaco_apam`.`a`.`task_id`) and (`c`.`employe_id` = `b`.`employe_id`));

-- list_task_final
CREATE OR REPLACE ALGORITHM=UNDEFINED DEFINER=`ptpemaco`@`localhost` SQL SECURITY DEFINER VIEW `ptpemaco_apam`.`list_task_final` AS
select `a`.`task_id` AS `task_id`,`a`.`task_title` AS `task_title`,`a`.`task_parent` AS `task_parent`,`a`.`division` AS `division`,`a`.`project_id` AS `project_id`,`z`.`project_name` AS `project_name`,`y`.`organization_name` AS `divisi`,`x`.`first_name` AS `created_by`,if((`ptpemaco_apam`.`b`.`progress` is null),((select sum(`ptpemaco_apam`.`d`.`progress`) from (`ptpemaco_apam`.`progress1` `d` join `ptpemaco_apam`.`keturunan_task` `c`) where ((`a`.`task_id` = `ptpemaco_apam`.`c`.`task_parent`) and (`ptpemaco_apam`.`d`.`task_id` = `ptpemaco_apam`.`c`.`task_id`))) / (select count(`ptpemaco_apam`.`c`.`task_id`) from `ptpemaco_apam`.`keturunan_task` `c` where (`a`.`task_id` = `ptpemaco_apam`.`c`.`task_parent`))),`ptpemaco_apam`.`b`.`progress`) AS `progress`,(select `w`.`start_date` from `ptpemaco_apam`.`project_task_approval` `w` where (`w`.`task_id` = `a`.`task_id`) order by `w`.`approval_id` desc limit 1) AS `start_date`,(select `w`.`end_date` from `ptpemaco_apam`.`project_task_approval` `w` where (`w`.`task_id` = `a`.`task_id`) order by `w`.`approval_id` desc limit 1) AS `end_date` from ((((`ptpemaco_apam`.`project_tasks` `a` join `ptpemaco_apam`.`progress1` `b`) join `ptpemaco_apam`.`projects` `z`) join `ptpemaco_apam`.`organizations` `y`) join `ptpemaco_apam`.`employees` `x`) where ((`a`.`task_id` = `ptpemaco_apam`.`b`.`task_id`) and (`a`.`project_id` = `z`.`project_id`) and (`z`.`division` = `y`.`organization_id`) and (`a`.`created_by` = `x`.`employe_id`));

-- pic_task
CREATE OR REPLACE ALGORITHM=UNDEFINED DEFINER=`ptpemaco`@`localhost` SQL SECURITY DEFINER VIEW `ptpemaco_apam`.`pic_task` AS
select `a`.`task_id` AS `task_id`,`b`.`first_name` AS `pic_name` from ((`ptpemaco_apam`.`project_tasks` `a` join `ptpemaco_apam`.`employees` `b`) join `ptpemaco_apam`.`project_task_pics` `c`) where ((`c`.`task_id` = `a`.`task_id`) and (`c`.`employe_id` = `b`.`employe_id`));

-- send_message
CREATE OR REPLACE ALGORITHM=UNDEFINED DEFINER=`ptpemaco`@`localhost` SQL SECURITY DEFINER VIEW `ptpemaco_apam`.`send_message` AS
select `a`.`id` AS `id`,`a`.`actor` AS `actor`,`a`.`s_wa` AS `s_wa`,(select `ptpemaco_apam`.`employees`.`first_name` from `ptpemaco_apam`.`employees` where (`ptpemaco_apam`.`employees`.`employe_id` = `a`.`actor`)) AS `actor_name`,`a`.`recipient` AS `recipient`,(select `ptpemaco_apam`.`employees`.`first_name` from `ptpemaco_apam`.`employees` where (`ptpemaco_apam`.`employees`.`employe_id` = `a`.`recipient`)) AS `reciepint_name`,`b`.`type` AS `type`,`c`.`entity` AS `entity`,`a`.`created_at` AS `created_at`,`b`.`message` AS `message`,coalesce((select (case when (`ptpemaco_hr_production`.`employee_personal_data`.`gender` = 'Laki-laki') then 'Bapak' when (`ptpemaco_hr_production`.`employee_personal_data`.`gender` = 'Perempuan') then 'Ibu' else 'Bapak/Ibu' end) from `ptpemaco_hr_production`.`employee_personal_data` where (`ptpemaco_hr_production`.`employee_personal_data`.`employe_id` = `a`.`recipient`) limit 1),'Bapak/Ibu') AS `panggilan`,(select (case when regexp_like(`ptpemaco_hr_production`.`employee_personal_data`.`phone_number`,'^08[0-9]{8,12}$') then concat('628',substr(`ptpemaco_hr_production`.`employee_personal_data`.`phone_number`,3)) when regexp_like(`ptpemaco_hr_production`.`employee_personal_data`.`phone_number`,'^628[0-9]{8,12}$') then `ptpemaco_hr_production`.`employee_personal_data`.`phone_number` when regexp_like(`ptpemaco_hr_production`.`employee_personal_data`.`phone_number`,'^[1-9][0-9]{6,15}$') then `ptpemaco_hr_production`.`employee_personal_data`.`phone_number` when regexp_like(`ptpemaco_hr_production`.`employee_personal_data`.`phone_number`,'^\\+[0-9]{6,15}$') then `ptpemaco_hr_production`.`employee_personal_data`.`phone_number` else NULL end) from `ptpemaco_hr_production`.`employee_personal_data` where (`ptpemaco_hr_production`.`employee_personal_data`.`employe_id` = `a`.`recipient`) limit 1) AS `pn`,concat('https://sys.ptpema.co.id/',`b`.`url`,if((`b`.`query_key` = ''),concat('/',`a`.`entity_id`),concat('?',`b`.`query_key`,'=',`a`.`entity_id`))) AS `url` from ((`ptpemaco_apam`.`notifications` `a` join `ptpemaco_apam`.`notification_entity_type` `b` on((`a`.`entity_type_id` = `b`.`id`))) join `ptpemaco_apam`.`notification_entity` `c` on((`b`.`entity_id` = `c`.`id`))) where ((`a`.`status` = 0) and (`a`.`s_wa` is null) and (cast(`a`.`created_at` as date) = curdate()));

-- task_latest_status
CREATE OR REPLACE ALGORITHM=UNDEFINED DEFINER=`ptpemaco`@`localhost` SQL SECURITY DEFINER VIEW `ptpemaco_apam`.`task_latest_status` AS
select `a`.`task_id` AS `task_id`,`b`.`task_parent` AS `task_parent`,`b`.`project_id` AS `project_id`,`b`.`division` AS `division`,`b`.`task_title` AS `task_title`,`b`.`task_desc` AS `task_desc`,`c`.`employe_id` AS `employe_id`,`c`.`first_name` AS `first_name`,`a`.`approval_id` AS `approval_id`,`a`.`status` AS `status`,`b`.`task_progress` AS `task_progress`,`a`.`start_date` AS `start_date`,`a`.`end_date` AS `end_date`,`d`.`first_name` AS `created_by`,`a`.`created_at` AS `send_date`,`b`.`updated_at` AS `updated_at`,`b`.`created_at` AS `created_at`,`b`.`sub` AS `sub`,`ptpemaco_apam`.`e`.`direct_atasan` AS `direct_atasan` from ((((`ptpemaco_apam`.`project_task_approval` `a` join `ptpemaco_apam`.`project_tasks` `b`) join `ptpemaco_apam`.`employees` `c`) join `ptpemaco_apam`.`employees` `d`) join `ptpemaco_apam`.`struktur_lengkap_oke` `e`) where (`a`.`approval_id` in (select max(`ptpemaco_apam`.`project_task_approval`.`approval_id`) from `ptpemaco_apam`.`project_task_approval` group by `ptpemaco_apam`.`project_task_approval`.`task_id`) and (`a`.`task_id` = `b`.`task_id`) and (`a`.`employe_id` = `c`.`employe_id`) and (`b`.`created_by` = `d`.`employe_id`) and (`a`.`employe_id` = `ptpemaco_apam`.`e`.`employe_id`));

DROP VIEW IF EXISTS `ptpemaco_apam`.`employees_hr`;

SELECT COUNT(*) AS view_lama_kembali FROM information_schema.views WHERE table_schema = 'ptpemaco_apam' AND table_name IN ('list_detail_pic_task', 'list_task_final', 'pic_task', 'send_message', 'task_latest_status') AND view_definition NOT LIKE '%employees_hr%';
